INSERT INTO articles (id, title, slug, type, content, excerpt, category, author, featured_image, is_published) VALUES (101, '7 Most Beautiful Cottages in Ontario for the Ultimate Escape', '7-most-beautiful-cottages-ontario', 'listicle', 'Ontario holds some of the most breathtaking nature escapes in North America. Whether you dream of watching misty mornings from a massive lakeside dock or drinking cocoa next to a custom stone fireplace, the province has a sanctuary built just for you.
INSERT INTO listicle_items (article_id, rank, title, description, rating, price, image, vibe, vrbo_link) VALUES (101, 1, 'The Blue Pines Sanctuary (Muskoka)', 'An architectural marvel crafted completely in white cedar, boasting a massive 50-foot private dock, an integrated historic boathouse lounge, and direct deep-water access to Muskoka''s premier lakes.', '4.97', 450, 'https://images.unsplash.com/photo-1507089947368-19c1da9775ae?auto=format&fit=crop&q=80&w=600', 'Prestige & Heritage', 'https://www.vrbo.com/search/keywords:muskoka-ontario-canada');
INSERT INTO listicle_items (article_id, rank, title, description, rating, price, image, vibe, vrbo_link) VALUES (101, 2, 'The Borealis A-Frame (Algonquin)', 'A beautifully reimagined mid-century A-frame right on the border of Algonquin Provincial Park. Highlights include a dramatic suspended hammock net over the light-flooded living space.', '4.92', 210, 'https://images.unsplash.com/photo-1549693578-d683be217e58?auto=format&fit=crop&q=80&w=600', 'Minimalist Design', 'https://www.vrbo.com/search/keywords:algonquin-park-ontario-canada');
INSERT INTO listicle_items (article_id, rank, title, description, rating, price, image, vibe, vrbo_link) VALUES (101, 3, 'The Bruce Peninsula Cliffside Villa', 'Perched dramatic high above the deep turquoise waters of Georgian Bay, this luxury villa features an infinity-edge hot tub built into a multi-tiered wrap-around cedar deck.', '4.89', 580, 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&q=80&w=600', 'Contemporary Luxury', 'https://www.vrbo.com/search/keywords:bruce-peninsula-ontario');
INSERT INTO listicle_items (article_id, rank, title, description, rating, price, image, vibe, vrbo_link) VALUES (101, 4, 'The Secret Haven of Tobermory', 'Hidden peacefully away in a forest of ancient silver birch trees, this eco-sensitive cottage offers a pebble beach cove perfect for launching kayaks at sunrise.', '4.85', 195, 'https://images.unsplash.com/photo-1499793983690-e29da59ef1c2?auto=format&fit=crop&q=80&w=600', 'Eco-Friendly Sanctuary', 'https://www.vrbo.com/search/keywords:tobermory-ontario');
INSERT INTO listicle_items (article_id, rank, title, description, rating, price, image, vibe, vrbo_link) VALUES (101, 5, 'Whispering Highlands Log Cabin (Haliburton)', 'A quintessential hand-scribed log home modernized with premium Scandinavian interiors. Features a custom stone fire pit carved directly into the Canadian Shield granite.', '4.91', 275, 'https://images.unsplash.com/photo-1449034446853-66c86144b0ad?auto=format&fit=crop&q=80&w=600', 'Cozy & Family-focused', 'https://www.vrbo.com/search/keywords:haliburton-ontario');
INSERT INTO listicle_items (article_id, rank, title, description, rating, price, image, vibe, vrbo_link) VALUES (101, 6, 'The Sandbanks Duneside Villa', 'An elegant glass-walled architectural home steps away from the majestic white sand dunes of Sandbanks. Outfitted with minimalist Nordic style and premium linen.', '4.95', 490, 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&q=80&w=600', 'Beachside Chic', 'https://www.vrbo.com/search/keywords:prince-edward-county-ontario');
INSERT INTO listicle_items (article_id, rank, title, description, rating, price, image, vibe, vrbo_link) VALUES (101, 7, 'The Hidden Stream Mill (Kawarthas)', 'A restored 19th-century watermill intersected by a tranquil trout stream. Exposed original beams combine with state-of-the-art automation to create a romantic retreat.', '4.88', 310, 'https://images.unsplash.com/photo-1523217582562-09d0def993a6?auto=format&fit=crop&q=80&w=600', 'Historical Romance', 'https://www.vrbo.com/search/keywords:kawartha-lakes-ontario');
